#include "unity.h"
#include "buffer.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_prepend_resize_and_success(void) {
    // Setup: create a buffer with small capacity and some initial data
    // We want self->len <= needed, so that buffer_resize is called and succeeds
    // Example: initial buffer size 5, data "bar" (len 3), prepend "foo" (len 3)
    // needed = 3 + 3 = 6 > 5, so resize is triggered

    buffer_t *buf = buffer_new_with_size(5);
    TEST_ASSERT_NOT_NULL(buf);
    memcpy(buf->data, "bar", 4); // includes null terminator

    // Prepend "foo"
    int ret = buffer_prepend(buf, "foo");
    TEST_ASSERT_EQUAL_INT(0, ret);

    // After prepend, buffer should contain "foobar"
    helper_assert_buffer_string_equals(buf, "foobar");
    helper_assert_buffer_length(buf, 6);

    // Cleanup
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_prepend_resize_and_success);
    return UNITY_END();
}


